use hs_loop::dshplan::PlanSession;use serde_json::json;
#[test]fn approved_review_only_leaves_at_next_boundary(){let mut p=PlanSession::default();p.select(true,false);assert!(p.active);let args=json!({"plan":"# Repair parser\nTest it."});let answer=json!({"answers":[{"id":"plan-review","selected":["Approve"]}]});assert_eq!(p.review(&args,Some(&answer)).unwrap(),json!({"approved":true}));assert!(p.active);assert_eq!(p.pending,Some(false));assert_eq!(p.boundary(),Some(false));assert!(!p.active);}
#[test]fn review_policy_and_feedback_fail_closed(){let args=json!({"plan":"# Plan\nSteps"});let mut p=PlanSession::default();assert!(p.review(&args,None).unwrap_err().contains("only available in plan mode"));p.select(true,false);assert!(p.review(&json!({"plan":"not heading"}),None).unwrap_err().contains("starting with a # heading"));assert!(p.review(&args,None).unwrap_err().contains("no user-questions channel"));for answer in [json!({"answers":[]}),json!({"answers":[{"id":"plan-review","selected":["Approve","Keep planning"]}]}),json!({"answers":[{"id":"plan-review","selected":["Approve"],"custom":"rethink"}]}),json!({"answers":[{"id":"plan-review","selected":["Approve"]},{"id":"plan-review","selected":["Approve"]}]})]{assert!(p.review(&args,Some(&answer)).unwrap_err().contains("keep planning"));assert!(p.active);assert_eq!(p.pending,None);}let e=p.review(&args,Some(&json!({"answers":[{"id":"plan-review","selected":["Keep planning"],"custom":"Use fixtures"}]}))).unwrap_err();assert!(e.ends_with("their feedback: Use fixtures"));}
#[test]fn contradictory_pending_selection_cancels_without_changing_active(){let mut p=PlanSession::default();assert_eq!(p.select(true,true),"queued");assert_eq!(p.select(true,true),"noop");assert_eq!(p.select(false,true),"cancelled");assert_eq!(p.boundary(),None);assert!(!p.active);}
fn rig(d:&std::path::Path)->hs_loop::InnerLoop{let cfg=d.join("rig");std::fs::write(&cfg,format!("[[models]]\nname='seqmodel'\ncommand=['{}']\ndefault=true\n",env!("CARGO_BIN_EXE_hs-plugin-seqmodel"))).unwrap();let mut lp=hs_loop::InnerLoop::new(hs_kernel::Kernel::load(&cfg).unwrap(),d,false,1).unwrap();lp.set_answer_root(Some(d.to_owned()));lp}
#[test]fn native_exit_review_is_pending_and_commits_before_next_actual_request_then_restores(){let d=tempfile::tempdir().unwrap();let mut lp=rig(d.path());lp.set_plan_guidance("Plan before acting.".into()).unwrap();assert_eq!(lp.select_plan_mode(true).unwrap(),"committed");lp.set_plan_reviewer(Box::new(|q|{assert_eq!(q["questions"][0]["detail"],"# Fix parser\nUse fixtures");assert_eq!(q["questions"][0]["intent"]["kind"],"plan-review");Ok(json!({"answers":[{"id":"plan-review","selected":["Approve"]}]}))}));assert_eq!(lp.dispatch_tool_for_test("exit_plan_mode",&json!({"plan":"# Fix parser\nUse fixtures"})).unwrap().output,json!({"approved":true}));assert_eq!(lp.plan_view(),json!({"active":true,"pending":true}));lp.run_mission("next-step").unwrap();assert_eq!(lp.plan_view(),json!({"active":false,"pending":false}));let id=lp.stream_id();drop(lp);let cfg=d.path().join("rig");let lp=hs_loop::InnerLoop::with_stream(hs_kernel::Kernel::load(&cfg).unwrap(),d.path(),id,false,1).unwrap();assert_eq!(lp.plan_view(),json!({"active":false,"pending":false}));let r=hs_log::StreamReader::open(d.path(),id).unwrap();let vals:Vec<serde_json::Value>=r.events().unwrap().iter().filter_map(|e|serde_json::from_slice(&r.resolve_payload(e).ok()?).ok()).collect();let states:Vec<_>=vals.iter().filter(|v|v["record_type"]=="plan/mode").collect();assert_eq!(states.len(),2);assert_eq!(states[0]["active"],true);assert_eq!(states[1]["active"],false);}
#[test]fn missing_review_channel_leaves_plan_active_and_legacy_gate_independent(){let d=tempfile::tempdir().unwrap();let mut lp=rig(d.path());lp.select_plan_mode(true).unwrap();let out=lp.dispatch_tool_for_test("exit_plan_mode",&json!({"plan":"# Plan\nSteps"})).unwrap();assert!(out.output["error"].as_str().unwrap().contains("no user-questions channel"));assert_eq!(lp.plan_view(),json!({"active":true,"pending":false}));assert!(!hs_loop::plan_mode::active(d.path()));lp.run_mission("planning").unwrap();let id=lp.stream_id();drop(lp);let lp=hs_loop::InnerLoop::with_stream(hs_kernel::Kernel::load(&d.path().join("rig")).unwrap(),d.path(),id,false,1).unwrap();assert_eq!(lp.plan_view()["active"],true);}
#[test]fn malformed_model_arguments_and_guidance_cannot_mutate_plan(){let d=tempfile::tempdir().unwrap();let mut lp=rig(d.path());assert!(lp.set_plan_guidance(" \n ".into()).is_err());lp.select_plan_mode(true).unwrap();for args in [json!({}),json!({"plan":1}),json!({"plan":"## Wrong"})]{assert!(lp.dispatch_tool_for_test("exit_plan_mode",&args).unwrap().output["error"].is_string());assert_eq!(lp.plan_view(),json!({"active":true,"pending":false}));}}
#[test]fn active_guidance_is_in_actual_request_and_exit_schema_stable(){let d=tempfile::tempdir().unwrap();let mut lp=rig(d.path());lp.set_plan_guidance("Deployment planning guidance.".into()).unwrap();lp.select_plan_mode(true).unwrap();lp.run_mission("guidance").unwrap();let r=hs_log::StreamReader::open(d.path(),lp.stream_id()).unwrap();let vals:Vec<serde_json::Value>=r.events().unwrap().iter().filter_map(|e|serde_json::from_slice(&r.resolve_payload(e).ok()?).ok()).collect();assert!(vals.iter().filter_map(|v|v["messages"].as_array()).any(|m|m.iter().any(|m|m["content"]=="Deployment planning guidance.")));assert_eq!(hs_loop::dshtools::schema("exit_plan_mode").unwrap()["input_schema"]["required"],json!(["plan"]));}
#[test]fn narration_compares_last_request_header_and_exit_is_silent(){let mut p=PlanSession::default();assert_eq!(p.narration(true),None);p.header();p.select(true,false);assert_eq!(p.narration(true),Some("The user switched this session to plan mode."));p.header();assert_eq!(p.narration(true),None);assert_eq!(p.narration(false),Some("The user switched this session back to the default mode."));}
#[test]fn user_switch_notice_survives_restart_and_only_next_request_has_it(){let d=tempfile::tempdir().unwrap();let mut lp=rig(d.path());lp.run_mission("before").unwrap();lp.select_plan_mode(true).unwrap();let id=lp.stream_id();drop(lp);let mut lp=hs_loop::InnerLoop::with_stream(hs_kernel::Kernel::load(&d.path().join("rig")).unwrap(),d.path(),id,false,1).unwrap();lp.run_mission("after").unwrap();lp.run_mission("steady").unwrap();let r=hs_log::StreamReader::open(d.path(),id).unwrap();let calls:Vec<serde_json::Value>=r.events().unwrap().iter().filter_map(|e|serde_json::from_slice::<serde_json::Value>(&r.resolve_payload(e).ok()?).ok()).filter(|v|v["messages"].is_array()).collect();assert_eq!(calls.len(),3);let has=|v:&serde_json::Value|v["messages"].as_array().unwrap().iter().any(|m|m["content"]=="The user switched this session to plan mode.");assert!(!has(&calls[0]));assert!(has(&calls[1]));assert!(!has(&calls[2]));}
#[test]fn approved_exit_has_no_duplicate_user_switch_notice_in_actual_request(){let d=tempfile::tempdir().unwrap();let mut lp=rig(d.path());lp.select_plan_mode(true).unwrap();lp.run_mission("planning").unwrap();lp.set_plan_reviewer(Box::new(|_|Ok(json!({"answers":[{"id":"plan-review","selected":["Approve"]}]}))));lp.dispatch_tool_for_test("exit_plan_mode",&json!({"plan":"# Approved\nSteps"})).unwrap();lp.run_mission("executing").unwrap();let r=hs_log::StreamReader::open(d.path(),lp.stream_id()).unwrap();let calls:Vec<serde_json::Value>=r.events().unwrap().iter().filter_map(|e|serde_json::from_slice::<serde_json::Value>(&r.resolve_payload(e).ok()?).ok()).filter(|v|v["messages"].is_array()).collect();assert!(!calls.last().unwrap()["messages"].as_array().unwrap().iter().any(|m|m["content"]=="The user switched this session back to the default mode."));}
#[test]fn opposite_idle_switch_before_request_clears_obsolete_notice_after_restart(){let d=tempfile::tempdir().unwrap();let mut lp=rig(d.path());lp.run_mission("default").unwrap();lp.select_plan_mode(true).unwrap();lp.select_plan_mode(false).unwrap();let id=lp.stream_id();drop(lp);let mut lp=hs_loop::InnerLoop::with_stream(hs_kernel::Kernel::load(&d.path().join("rig")).unwrap(),d.path(),id,false,1).unwrap();lp.run_mission("still-default").unwrap();let r=hs_log::StreamReader::open(d.path(),id).unwrap();let calls:Vec<serde_json::Value>=r.events().unwrap().iter().filter_map(|e|serde_json::from_slice::<serde_json::Value>(&r.resolve_payload(e).ok()?).ok()).filter(|v|v["messages"].is_array()).collect();assert!(!calls.last().unwrap()["messages"].as_array().unwrap().iter().any(|m|m["content"]=="The user switched this session to plan mode."));}
